import{_ as d}from"./index-BAkwCzTZ.js";import{az as s}from"./@vue-De9RwyRn.js";import"./element-plus-CKJIAC2w.js";import"./lodash-es-Ceiv_TW4.js";import"./@vueuse-Ihwzeb_o.js";import"./@element-plus-B-y2LHuz.js";import"./async-validator-j0i5Y79Y.js";import"./@popperjs-DxtSUbXb.js";import"./@ctrl-DGnlsNIE.js";import"./dayjs-KsS9adaU.js";import"./memoize-one-BAtLgO95.js";import"./normalize-wheel-es-TzhA1irr.js";import"./@floating-ui-BQjuueHq.js";import"./pinia-Dndd2XNl.js";import"./crypto-js-B6L3KfD1.js";import"./vue-i18n-DB7lm_w-.js";import"./@intlify-D8hALvN4.js";import"./vue-router-DNsliMEH.js";import"./pinia-plugin-persistedstate-COWkwNh5.js";const t=d({},[["render",function(d,t){return t[0]||(t[0]=s('<div class="helpBoxTop" data-v-87dd0997>一、计划配置</div><div class="helpBoxTopChild" data-v-87dd0997>录像计划</div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 当IPC安装有SD卡，且能够正常工作后，可配置IPC的录像计划。配置录像计划后，IPC将自动在配置的时间内执行不同的录像任务并将该录像保存至存储设备中。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 勾选“启用”，选择录像类型，按住鼠标左键，在时间条上拖动鼠标，即可进行录像计划的编辑。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 鼠标悬浮到时间条上，单击时间条右侧的【复制到】，可以选择将相同配置复制到其他时间和其他通道。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 高级配置 <ul data-v-87dd0997><li data-v-87dd0997> 预录时间：录像开始前的预先录像时间，不预录表示不进行预先录像，不受限制表示按照最大预录时间进行预先录像。最大预录时间按照2Mbps码率计算，随着码流选择更高，预录时间会变短。 </li><li data-v-87dd0997>录像延时：录像的延时时间。</li><li data-v-87dd0997>码流类型：选择主码流或者子码流进行录像。</li></ul></div><div class="helpBoxTop" data-v-87dd0997>二、存储管理</div><div class="helpBoxTopChild" data-v-87dd0997>轻存储</div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 1、进入“配置→存储→存储管理→“轻存储”，进入轻存储配置界面。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 2、配置磁盘配额：勾选存储设备，然后设置各个设备的磁盘配额，包括图片容量、录像容量等。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 3、存储时间，设备根据可用存储卡空间和等级，摄像机会自动计算码率并提供推荐的存储时间； </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 下方提示：该时间基于录像质量估算，仅供参考，抓图不计入存储时间。 </div><div class="helpDesText" style="margin-top:8px;" data-v-87dd0997> 说明：启用轻存储后，未格式化的存储卡将自动格式化，已格式化的存储卡不需要再次格式化。 </div>',13))}],["__scopeId","data-v-87dd0997"]]);export{t as default};
